"""Historical metadata validation, never historical candidate execution."""
import json
from pathlib import Path
import subprocess

# Last published source before the structural-candidate amendment. Frozen
# documents are compared with their Git originals, not regenerated by new code.
PRE_STRUCTURAL_SOURCE='b404deb3e0a440364d7c1835d21a13046968e370'
LATER_HISTORICAL_SOURCES={
    'experiments/manifests/single_prompt_completed_ab_test_v13.json':
        '395909a6683ffac51d711bb1a98f651b023d4e4b',
}

def validate_published_single_prompt(root,path,value):
    """Return whether this is a pinned historical document; reject any mutation.

    No providers, algorithm imports, old Guard implementation or execution
    eligibility are supplied. Runtime startup still requires its exact freeze.
    """
    if not isinstance(value,dict) or not str(value.get('schema_version','')).startswith('single_prompt_'):
        return False
    path=Path(path).as_posix()
    if not path.startswith('experiments/manifests/') or '..' in Path(path).parts:return False
    source=LATER_HISTORICAL_SOURCES.get(path,PRE_STRUCTURAL_SOURCE)
    result=subprocess.run(['git','show',source+':'+path],cwd=root,capture_output=True)
    if result.returncode:return False
    original=json.loads(result.stdout)
    if value!=original:raise ValueError('PUBLISHED_HISTORICAL_MANIFEST_CHANGED: '+path)
    return True
